using Sms.Core.Cpu;

namespace Sms.Core.Tests.Cpu;

// Partial numeric extracts from record 0000 of each cb NN.json, SingleStepTests/z80
// revision ebe1875d48f374bcfd4b505d8eb8ee751568b5f7 (MIT; see Fixtures license).
// Source: https://github.com/SingleStepTests/z80/tree/ebe1875d48f374bcfd4b505d8eb8ee751568b5f7/v1
// These vectors are generated by another emulator, not hardware. Only the fields
// listed below are asserted; hidden state, other registers and pin traces are blocked.
public sealed class Z80ExternalRotateVectorsTests
{
    [Theory]
    [InlineData(0x00, 189, 234, 69, 51223, 123, 45, 71, 51225)]
    [InlineData(0x08, 146, 206, 79, 51783, 73, 8, 81, 51785)]
    [InlineData(0x10, 31, 130, 121, 39161, 62, 40, 123, 39163)]
    [InlineData(0x18, 0, 44, 85, 44371, 0, 68, 87, 44373)]
    [InlineData(0x20, 120, 112, 25, 31643, 240, 164, 27, 31645)]
    [InlineData(0x28, 178, 145, 81, 28807, 217, 136, 83, 28809)]
    [InlineData(0x38, 144, 35, 100, 56997, 72, 12, 102, 56999)]
    public void FirstExternalVectorForEachRotateShiftFamily(
        byte opcode, byte b, byte f, byte refresh, ushort pc,
        byte expectedB, byte expectedF, byte expectedRefresh, ushort expectedPc)
    {
        var bus = new Bus();
        bus.Memory[pc] = 0xcb;
        bus.Memory[unchecked((ushort)(pc + 1))] = opcode;
        var cpu = new Z80(bus) { B = b, F = f, Refresh = refresh, ProgramCounter = pc };

        Assert.Equal(8, cpu.Step()); // Upstream trace contains eight sampled T-states.
        Assert.Equal(expectedB, cpu.B);
        Assert.Equal(expectedF, cpu.F);
        Assert.Equal(expectedRefresh, cpu.Refresh);
        Assert.Equal(expectedPc, cpu.ProgramCounter);
    }

    private sealed class Bus : IZ80Bus
    {
        public byte[] Memory { get; } = new byte[65536];
        public byte FetchOpcode(ushort address) => Memory[address];
        public byte ReadMemory(ushort address) => throw new InvalidOperationException("Unexpected read");
        public void WriteMemory(ushort address, byte value) => throw new InvalidOperationException("Unexpected write");
        public byte ReadIo(ushort port) => throw new InvalidOperationException("Unexpected I/O");
        public void WriteIo(ushort port, byte value) => throw new InvalidOperationException("Unexpected I/O");
        public byte AcknowledgeInterrupt() => throw new InvalidOperationException("Unexpected acknowledge");
    }
}
